mod solution;

fn main() {
    let cases = [
    (r#"push5 push2 push4 pop min"#, r#"2"#),
    (r#"push7 push3 pop min"#, r#"7"#),
    (r#"
push7 push3 pop min
"#, r#"7"#),
    (r#"  
push5 push2 push4 pop min
  "#, r#"2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS min-stack");
}
